import {materializeConcreteOriginalGit} from './portable-git-fixtures.mjs';
import test, {after} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync,mkdtempSync,rmSync,realpathSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {gzipSync} from 'node:zlib';
import {transportConcreteSyntaxSource,transportConcreteSyntaxMeta,
  serializeConcreteSyntaxMeta,parseConcreteSyntaxMeta,reconstructConcreteSyntax} from '../concrete-syntax-meta.mjs';
import {createRustConcreteSyntaxStage,readRustConcreteSyntaxMeta} from '../forward-concrete-syntax.mjs';
import {prepareReverseConcreteSource,parseReverseConcreteSource} from '../js-to-rust/concrete-source.mjs';
import {translateSource,translateSourceConcreteSyntaxMeta} from '../translate.mjs';
import {verifyTypedTargets} from './typed-targets.mjs';

// Independent complete pre-277 modules, including their original comments and
// imports. All three equal Git 3f83171fe5ae5a51058482070a0c75442b08ad26.
// These baseline modules retain their own old pipeline, not the new transaction.
// Their upstream repository license remains the repository LICENSE file.
const BASELINES=[{"label":"core","logical":"concrete-syntax-meta.mjs","bytes":22540,"sha256":"127226ca4dc71123bb96a45a9a91fc120914f1464ac4fec05634fa54a61421b3","base64":""},{"label":"forward","logical":"forward-concrete-syntax.mjs","bytes":1333,"sha256":"8a77f9349fd264f0d540c355f1b5437f5b53f294bfe8dbd68afad0bbb5168284","base64":""},{"label":"reverse","logical":"js-to-rust/concrete-source.mjs","bytes":2306,"sha256":"df2c1d65b2e2444b0ca6451335f5366fde2e18fcfa77074351319b288fbe613b","base64":""}];
const json=JSON.stringify,parse=JSON.parse,define=Object.defineProperty,descriptor=Object.getOwnPropertyDescriptor;
const digest=value=>createHash('sha256').update(value).digest('hex');
const phases=()=>({languageRules:[],repositoryRules:[]});
const emptyTrace=[{phase:'language',rules:[]},{phase:'repository',rules:[]}];
function retain(name,value){
  const directory=process.env.ROUTER_CONCRETE_TRANSACTION_VECTOR_DIR;if(!directory)return;
  mkdirSync(directory,{recursive:true});
  const text=json(value,(_key,item)=>typeof item==='bigint'?{$bigint:item.toString()}:item);
  writeFileSync(join(directory,name+'.json.gz'),gzipSync(Buffer.from(text+'\n')),{flag:'wx'});
}
function outcome(read){try{return {value:read()};}catch(error){return {error:{name:error.name,message:error.message,stack:error.stack}};}}
function sameOutcome(left,right){
  assert.equal(Boolean(left.error),Boolean(right.error));
  if(left.error)assert.equal(left.error.name,right.error.name);else assert.deepEqual(right.value,left.value);
}
const scratch=realpathSync(mkdtempSync(join(tmpdir(),'router-cst-transaction-baseline-')));
after(()=>rmSync(scratch,{recursive:true,force:true}));
const copies=new Map(BASELINES.map(row=>[row.logical,pathToFileURL(join(scratch,row.label+'.mjs')).href]));
const baselineEvidence=[];
for(const row of BASELINES){
  const original=Buffer.from(row.base64,'base64'),source=original.toString('utf8');
  assert.equal(original.length,row.bytes);assert.equal(digest(original),row.sha256);
  const origin=new URL('../'+row.logical,import.meta.url),relocations=[];
  const relocated=source.replace(/(\bfrom\s*)(['"])(\.\.?\/[^'"]+)\2/gu,(whole,prefix,quote,path)=>{
    const resolved=new URL(path,origin),core=resolved.href===new URL('../concrete-syntax-meta.mjs',import.meta.url).href;
    const replacement=prefix+json(core?copies.get('concrete-syntax-meta.mjs'):resolved.href);
    relocations.push({whole,replacement});return replacement;
  });
  let reversed=relocated;
  for(const change of [...relocations].reverse())reversed=reversed.replace(change.replacement,change.whole);
  assert.equal(reversed,source);
  const copy=fileURLToPath(copies.get(row.logical));writeFileSync(copy,relocated,{flag:'wx'});
  const readback=readFileSync(copy,'utf8');assert.equal(readback,relocated);
  baselineEvidence.push({label:row.label,logical:row.logical,original,source,sha256:row.sha256,
    origin:origin.href,copy:copies.get(row.logical),relocations,relocated,reversed,readback});
}
retain('00-complete-baseline-sources',baselineEvidence);
const oldCore=await import(copies.get('concrete-syntax-meta.mjs'));
const oldForward=await import(copies.get('forward-concrete-syntax.mjs'));
const oldReverse=await import(copies.get('js-to-rust/concrete-source.mjs'));
function previousSource(source,language){
  const created=oldCore.createConcreteSyntaxMeta(source,{language});
  const applied=oldCore.applyConcreteSyntaxSubstitutions(created,phases());
  const meta=oldCore.serializeConcreteSyntaxMeta(applied.value),document=oldCore.parseConcreteSyntaxMeta(meta);
  return {source:oldCore.reconstructConcreteSyntax(document),document,meta,trace:applied.trace};
}
function previousMeta(serialized){
  const parsed=oldCore.parseConcreteSyntaxMeta(serialized),applied=oldCore.applyConcreteSyntaxSubstitutions(parsed,phases());
  const meta=oldCore.serializeConcreteSyntaxMeta(applied.value),document=oldCore.parseConcreteSyntaxMeta(meta);
  return {source:oldCore.reconstructConcreteSyntax(document),document,meta,trace:applied.trace};
}
function visible(result,source,language){
  assert.deepEqual(Object.keys(result),['source','document','meta','trace']);
  assert.equal(result.source,source);assert.equal(result.document.source,source);assert.equal(result.document.language,language);
  assert.equal(result.document.schema,'meta-language-concrete-syntax-v1');
  assert.equal(result.document.representationLevel,'concrete-syntax');
  assert.deepEqual(result.document.authority,{type:false,owner:false,executable:false});
  assert.deepEqual(result.trace,emptyTrace);assert.ok(Object.isFrozen(result.document));
  assert.ok(Object.isFrozen(result.document.nodes));for(const row of result.document.nodes)assert.ok(Object.isFrozen(row));
  const leaves=result.document.nodes.filter(row=>row[0]!=='root'&&row[0]!=='group');
  assert.equal(leaves.map(row=>source.slice(row[2],row[3])).join(''),source);
  assert.equal(Buffer.from(result.source).equals(Buffer.from(source)),true);
  assert.deepEqual(parseConcreteSyntaxMeta(result.meta),result.document);
  assert.equal(serializeConcreteSyntaxMeta(result.document),result.meta);
  assert.equal(reconstructConcreteSyntax(result.document),source);
}
function compareSource(source,language,label){
  const before=previousSource(source,language),current=transportConcreteSyntaxSource(source,{language});
  const fromMeta=transportConcreteSyntaxMeta(before.meta);
  retain(label,{source,language,before,current,fromMeta});
  assert.deepEqual(current,before);assert.deepEqual(fromMeta,before);visible(current,source,language);
  return current;
}

test('fixed transactions preserve complete retained Router parents and complete original JavaScript provider source',{timeout:60000},t=>{
  const {root}=materializeConcreteOriginalGit(t),head='3f83171fe5ae5a51058482070a0c75442b08ad26';
  const selected=[['src/lib.rs','Rust','3c9605387b5454634325dbbf7604e0ad919931be17dac05905a60ea0268286af'],
    ['src/github_proxy.rs','Rust','3c65440f41bef37e9f55641ae298a8083884a42cffa9797e6c8ab40e81ef4e37'],
    ['src/responses_chat_input.rs','Rust','d234872e60a23b40b07261f63d870bafb5706993157b43e7a3794baaf7b69ef0'],
    ['tools/translation/vendor/meta-language/translation/lexer.js','JavaScript',"70dbe490cd5162661a665bdffd5b506093bebc5a515f6fc1d36ecc347b705fdc"]];
  for(const [index,[path,language,sha256]]of selected.entries()){
    const bytes=execFileSync('git',['show',head+':'+path],{cwd:root,timeout:10000,maxBuffer:8*1024*1024});
    const source=bytes.toString('utf8'),before=previousSource(source,language),current=transportConcreteSyntaxSource(source,{language});
    retain('01-original-'+index,{head,path,sha256,bytes,source,before,current,sourceAuthority:false});
    assert.equal(digest(bytes),sha256);assert.equal(Buffer.from(source).equals(bytes),true);
    assert.deepEqual(current,before);visible(current,source,language);
  }
});

test('full token trivia delimiter Unicode and source coordinates agree with the old independent pipeline',{timeout:60000},()=>{
  const cases=[['Rust','\ufeff// Ω😀\r\n/* outer { /* nested ] */ tail */\r\nmacro_rules! m {($e:expr)=>{{$e}};}\r\nfn x(){let r=br###"raw { /* ] 😀"###;m!(r);}\r\n'],
    ['JavaScript','\ufeff// Ω😀\r\nconst pattern=/[{}\\/]/gu;const text=`outer ${flag ? `inner ${1}` : /[}]/.source}`;\r\nfunction x(){return\r\n({text});}\r\n'],
    ['TypeScript','// typed Ω😀\r\nexport function x(value: readonly [number,string]): number {const text: string=`${value[1]}`;return value[0];}\r\n'],
    ['JavaScript','function quotient(a,b){return a / b;}']];
  for(const [index,[language,source]]of cases.entries()){
    const result=compareSource(source,language,'02-full-coordinates-'+index),doc=result.document;
    assert.equal(doc.sourceEncoding.utf16CodeUnits,source.length);
    assert.equal(doc.sourceEncoding.utf8Bytes,new TextEncoder().encode(source).length);
    for(const node of doc.nodes){
      for(const [codeUnit,byte]of [[node[2],node[4]],[node[3],node[5]]]){
        const split=codeUnit>0&&codeUnit<source.length&&/[\uD800-\uDBFF]/u.test(source[codeUnit-1])&&/[\uDC00-\uDFFF]/u.test(source[codeUnit]);
        if(split)assert.equal(byte,null);else assert.equal(byte,new TextEncoder().encode(source.slice(0,codeUnit)).length);
      }
    }
    if(index<3){assert.equal(doc.status,'lexical');assert.ok(doc.nodes.some(row=>row[0]==='group'));}
    else assert.equal(doc.status,'opaque');
  }
});

test('complete original forward and reverse helper contracts retain every visible field for source and serialized ingress',{timeout:60000},()=>{
  const examples=[['Rust','// Ω\r\npub fn choose(flag:bool)->u8{if flag{7}else{9}}'],
    ['JavaScript','// Ω\r\nexport function choose(flag){return flag ? 7 : 9;}'],
    ['TypeScript','// Ω\r\nexport function choose(flag: boolean): number{return flag ? 7 : 9;}']];
  for(const [index,[language,source]]of examples.entries()){
    const baseline=previousSource(source,language);
    const before=language==='Rust'?oldForward.createRustConcreteSyntaxStage(source):oldReverse.prepareReverseConcreteSource(source,language);
    const current=language==='Rust'?createRustConcreteSyntaxStage(source):prepareReverseConcreteSource(source,language);
    const beforeMeta=language==='Rust'?oldForward.readRustConcreteSyntaxMeta(baseline.meta):oldReverse.parseReverseConcreteSource(baseline.meta);
    const currentMeta=language==='Rust'?readRustConcreteSyntaxMeta(baseline.meta):parseReverseConcreteSource(baseline.meta);
    retain('03-complete-ingress-'+index,{source,language,baseline,before,current,beforeMeta,currentMeta});
    assert.deepEqual(current,before);assert.deepEqual(currentMeta,beforeMeta);assert.deepEqual(currentMeta,current);
    if(language==='Rust')assert.deepEqual(current,{source,document:baseline.document});
    else assert.deepEqual(current,{source,concreteSyntax:{schema:'router-reverse-concrete-stage-v1',language,
      representationLevel:baseline.document.representationLevel,status:baseline.document.status,meta:baseline.meta,trace:emptyTrace}});
  }
  const rust=previousSource('fn x(){}','Rust').meta,javascript=previousSource('function x(){}','JavaScript').meta;
  const refusals=[{label:'forward foreign language',before:outcome(()=>oldForward.readRustConcreteSyntaxMeta(javascript)),current:outcome(()=>readRustConcreteSyntaxMeta(javascript))},
    {label:'reverse foreign language',before:outcome(()=>oldReverse.parseReverseConcreteSource(rust)),current:outcome(()=>parseReverseConcreteSource(rust))}];
  retain('03-whole-helper-refusals',refusals);
  for(const row of refusals){sameOutcome(row.before,row.current);assert.equal(row.current.error?.name,'TypeError');}
});

test('canonical edited source passes the transaction and executes independent JavaScript and strict TypeScript',{timeout:60000},async()=>{
  const sources=[['JavaScript','export function compute(value){return value + 1;}\nexport const translated={compute};\n'],
    ['TypeScript','export function compute(value: number): number{return value + 1;}\nexport const translated={compute};\n']];
  const rows=[];
  for(const [language,source]of sources){
    const doc=oldCore.createConcreteSyntaxMeta(source,{language}),node=doc.nodes.findIndex(row=>row[1]==='number');
    const rules={languageRules:[{id:'one-to-two',edits:[{node,expected:'1',replacement:'2'}]}],
      repositoryRules:[{id:'retained-end-comment',edits:[{span:[source.length,source.length],expected:'',replacement:'// repository\n'}]}]};
    const edited=oldCore.applyConcreteSyntaxSubstitutions(doc,rules),meta=oldCore.serializeConcreteSyntaxMeta(edited.value);
    const before=previousMeta(meta),current=transportConcreteSyntaxMeta(meta),expected=source.replace(' + 1;',' + 2;')+'// repository\n';
    rows.push({language,source,doc,rules,edited,meta,before,current,expected});
  }
  retain('04-complete-edits-before-execution',rows);
  for(const row of rows){assert.deepEqual(row.current,row.before);visible(row.current,row.expected,row.language);
    assert.equal(oldCore.reconstructConcreteSyntax(row.doc),row.source);assert.deepEqual(row.edited.trace.map(item=>item.phase),['language','repository']);}
  const observations=[];
  await verifyTypedTargets({javascript:rows[0].current.source,typescript:rows[1].current.source},api=>{
    observations.push({zero:api.compute(0),three:api.compute(3),negative:api.compute(-3)});
    retain('04-runtime-'+observations.length,observations.at(-1));
  },{childTimeoutMs:20000});
  retain('04-all-runtime',observations);assert.deepEqual(observations,[{zero:2,three:5,negative:-1},{zero:2,three:5,negative:-1}]);
});

test('canonical shape source partitions classification authority and malformed text reject with full before-current observations',{timeout:60000},()=>{
  const source='pub fn original()->u8{12}',valid=previousSource(source,'Rust'),mutations=[];
  const changes=[['owner',value=>{value.authority.owner=true;}],['extra',value=>{value.extra=true;}],
    ['root-span',value=>{value.nodes[0][3]--;}],['parent',value=>{value.nodes[1][6]=1;}],
    ['class',value=>{value.nodes.find(row=>row[1]==='number')[1]='identifier';}],
    ['encoding',value=>{value.sourceEncoding.utf8Bytes++;}],['missing-node',value=>{value.nodes.splice(2,1);}],
    ['source-only',value=>{value.source='pub fn changed(){}';}],['status',value=>{value.status='opaque';}]];
  for(const [label,change]of changes){const copy=parse(valid.meta);change(copy);mutations.push({label,text:json(copy)});}
  mutations.push({label:'leading-space',text:' '+valid.meta},{label:'trailing-newline',text:valid.meta+'\n'},
    {label:'duplicate-schema',text:valid.meta.replace('{','{"schema":"ignored",')},{label:'truncated',text:valid.meta.slice(0,-1)},
    {label:'unknown-top-array',text:'[]'},{label:'nonprimitive',text:{toString(){throw Error('must not coerce');}}});
  const results=mutations.map(row=>({...row,before:outcome(()=>previousMeta(row.text)),current:outcome(()=>transportConcreteSyntaxMeta(row.text))}));
  const copied=structuredClone(valid.document),copyText=serializeConcreteSyntaxMeta(copied),copiedResult=transportConcreteSyntaxMeta(copyText);
  retain('05-complete-refusal-and-copy-controls',{source,valid,results,copied,copyText,copiedResult});
  for(const row of results){sameOutcome(row.before,row.current);assert.equal(row.current.error?.name,'TypeError',row.label);}
  assert.deepEqual(copiedResult,valid);assert.deepEqual(copiedResult.document.authority,{type:false,owner:false,executable:false});
});

test('whole opaque error deep syntax and lone UTF16 preserve source without supplying syntax or execution permission',{timeout:60000},()=>{
  const cases=[['Rust','/* outer /* nested */'],['Rust','fn broken(){r###"unterminated'],
    ['JavaScript','const value=`unterminated ${1};'],['TypeScript','function broken(value: string){return "unterminated;}'],
    ['Rust','('.repeat(260)+'value'+')'.repeat(260)],['JavaScript','['.repeat(260)+'0'+']'.repeat(260)],
    ['Rust','// '+String.fromCharCode(0xd800)+' '+String.fromCharCode(0xdfff)+'\nfn x(){}'],
    ['JavaScript','// '+String.fromCharCode(0xd800)+'\nexport const x=1;'],['Rust',''],['TypeScript',' \t\r\n\ufeff']];
  const rows=[];
  for(const [language,source]of cases){const before=previousSource(source,language),current=transportConcreteSyntaxSource(source,{language});
    rows.push({language,source,before,current,serialized:transportConcreteSyntaxMeta(before.meta)});}
  retain('06-whole-opaque-errors-and-utf16',rows);
  for(const [index,row]of rows.entries()){
    assert.deepEqual(row.current,row.before);assert.deepEqual(row.serialized,row.before);visible(row.current,row.source,row.language);
    if(index<6){assert.ok(['opaque','error'].includes(row.current.document.status));assert.equal(row.current.document.nodes.length,2);}
    if(index===6||index===7){assert.equal(row.current.document.sourceEncoding.wellFormedUnicode,false);
      assert.equal(row.current.document.sourceEncoding.utf8BytePreservation,false);assert.equal(row.current.document.sourceEncoding.utf8Mapping,'unicode-replacement');}
  }
});

test('fresh immutable results copied fidelity input bounded source and own-data options retain independent visible contracts',{timeout:60000},()=>{
  const source='fn value(){1}',first=transportConcreteSyntaxSource(source,{language:'Rust'}),second=transportConcreteSyntaxSource(source,{language:'Rust'});
  const third=transportConcreteSyntaxMeta(first.meta),copy=parse(first.meta);copy.authority.type=true;
  const frozenMutation=outcome(()=>{first.document.nodes[0][2]=1;});
  const changedCopy=outcome(()=>transportConcreteSyntaxMeta(json(copy)));
  let calls=0;const accessor={get language(){calls++;throw Error('language getter');}},inherited=Object.create({language:'Rust'});
  const proxy=new Proxy({language:'Rust'},{get(){calls++;throw Error('proxy get');},ownKeys(){calls++;throw Error('proxy keys');},getOwnPropertyDescriptor(){calls++;throw Error('proxy descriptor');}});
  const controls=[['accessor',source,accessor],['inherited',source,inherited],['proxy',source,proxy],
    ['extra',source,{language:'Rust',skip:true}],['boxed-source',new String(source),{language:'Rust'}],['language',source,{language:'C'}]];
  const refusals=controls.map(([label,text,options])=>({label,before:outcome(()=>oldCore.createConcreteSyntaxMeta(text,options)),current:outcome(()=>transportConcreteSyntaxSource(text,options))}));
  const limitSource=' '.repeat(2097152),beforeLimit=previousSource(limitSource,'Rust'),currentLimit=transportConcreteSyntaxSource(limitSource,{language:'Rust'});
  const overSource=limitSource+' ',over={before:outcome(()=>previousSource(overSource,'Rust')),current:outcome(()=>transportConcreteSyntaxSource(overSource,{language:'Rust'}))};
  retain('07-isolation-and-bounds',{source,first,second,third,copy,frozenMutation,changedCopy,refusals,calls,
    limitSource,beforeLimit,currentLimit,overSource,over});
  assert.deepEqual(first,second);assert.deepEqual(third,first);assert.notEqual(first.document,second.document);
  assert.notEqual(first.document.nodes,second.document.nodes);assert.notEqual(first.document.nodes[0],second.document.nodes[0]);
  assert.notEqual(first.document,third.document);assert.equal(frozenMutation.error?.name,'TypeError');assert.equal(changedCopy.error?.name,'TypeError');
  assert.equal(calls,0);for(const row of refusals){sameOutcome(row.before,row.current);assert.equal(row.current.error?.name,'TypeError',row.label);}
  assert.deepEqual(currentLimit,beforeLimit);visible(currentLimit,limitSource,'Rust');sameOutcome(over.before,over.current);assert.equal(over.current.error?.name,'TypeError');
});

test('edited Rust transactions feed actual semantic checks JS strict TS and preserve the original four option getter reads',{timeout:60000},async()=>{
  const source='pub fn choose(flag:bool)->u8{if flag{7}else{9}}',doc=oldCore.createConcreteSyntaxMeta(source,{language:'Rust'}),start=source.indexOf('9');
  const edited=oldCore.applyConcreteSyntaxSubstitutions(doc,{languageRules:[{id:'nine-to-eleven',edits:[{span:[start,start+1],expected:'9',replacement:'11'}]}],repositoryRules:[]});
  const text=oldCore.serializeConcreteSyntaxMeta(edited.value),stage=transportConcreteSyntaxMeta(text),result=translateSourceConcreteSyntaxMeta(stage.meta);
  const expected=source.slice(0,start)+'11'+source.slice(start+1),events=[],oldParse=descriptor(JSON,'parse');let hookCalls=0,ordered;
  const options={get projectDeclarations(){events.push('projectDeclarations');define(JSON,'parse',oldParse);return [];},
    get projectSourceScopes(){events.push('projectSourceScopes');return [];},get jsonParserProfile(){events.push('jsonParserProfile');return undefined;},
    get cargoManifest(){events.push('cargoManifest');return undefined;}};
  try{define(JSON,'parse',{...oldParse,value:function changedParse(){hookCalls++;throw Error('getter must restore before CST');}});
    ordered=outcome(()=>translateSource(source,'input.rs',options));}
  finally{define(JSON,'parse',oldParse);}
  const ordinary=translateSource(source),refusedSource='pub fn blocked()->bool{unknown!()}',refusedStage=transportConcreteSyntaxSource(refusedSource,{language:'Rust'});
  const refused=translateSourceConcreteSyntaxMeta(refusedStage.meta);
  retain('08-real-semantic-work-before-execution',{source,doc,edited,text,stage,result,expected,events,ordered,ordinary,hookCalls,refusedSource,refusedStage,refused});
  assert.equal(stage.source,expected);assert.equal(result.ir.sourceSha256,digest(expected));
  assert.deepEqual(result.ir.concreteSyntaxMeta,stage.document);assert.equal(result.ir.counts.executableFunctions,1);
  assert.deepEqual(events,['projectDeclarations','projectSourceScopes','jsonParserProfile','cargoManifest']);assert.equal(hookCalls,0);
  assert.ok(ordered.value);assert.deepEqual(ordered.value,ordinary);
  assert.equal(refused.ir.items.some(row=>row.name==='blocked'&&row.status==='executable'),false);
  const observations=[];
  await verifyTypedTargets(result,api=>{const row={yes:api.choose(true),no:api.choose(false),invalid:outcome(()=>api.choose('true'))};
    observations.push(row);retain('08-runtime-'+observations.length,row);},{childTimeoutMs:20000});
  retain('08-all-runtime',observations);assert.equal(observations.length,2);
  for(const row of observations){assert.equal(row.yes,7n);assert.equal(row.no,11n);assert.equal(row.invalid.error?.name,'TypeError');}
});
